#include <cmath>

using namespace std;

int digitLength(int sum) {
    if (sum == 0) return 1; // Handle case for 0
    int count = 0;
    while (sum != 0) {
        sum /= 10; // Remove the last digit
        count++;   // Increment count for each digit removed
    }
    return count; // Return the total digit count
}

void problemOne() {
    int a, b;
    while (scanf("%d %d", &a, &b) == 2) {
        printf("%d\n", digitLength(a + b)); // Call to the length function
    }
}

int main() {
    problemOne();
}

